      SUBROUTINE MISGETCC     GET PARAMETERS DESCRIBING MISALIGNMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM8L.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'XRAN.CIN'CC     LOCAL VARIABLESC      INTEGER         I2MOD, IMIS, INDX, J      INTEGER         MCF      REAL            DATAR      EXTERNAL        DATARCC-------------------------------------------------------------------C     MAGNITUDE OF ALIGNMENT IN EACH COORDINATEC      IMIS = ISTOR(NMIS)      VMMAX = 0.0      DO 10 J = 1, 6      I2MOD = 2 - MOD(J,2)      INDX = IMIS + J      VM(J) = DATAR(INDX)*UMIS(I2MOD)      VMMAX = AMAX1(VMMAX,ABS(VM(J)))   10 CONTINUECC     ALIGNMENT CODEC      TYT = INT(DATA(IMIS+7))      IF (VMMAX .EQ. 0.0 .AND. NV3 .EQ. 0) THEN        TYT = 0        GO TO 40      ENDIF      LFM = TYT/100      LTAB = MOD(TYT/10,10)      IF (TYPE .EQ. 6 .OR. TYPE .EQ. 37) THEN        RORC = MOD(TYT,10)        IR = RORC + 1        NUPD = IR      ENDIFC      IF (IPTOJ(8) .EQ. 0) THEN        MCF = MCFO      ELSE        MCF = INT(DATA(IMIS+8))      ENDIF      TMK = MCF/100      CHORD = MOD(MCF/10,10) .EQ. 0      FEO = MOD(MCF,10) .EQ. 1CC     RANDOM MISALIGNMENTC      IF (LFM .GE. 2) THEN        IF (BEFORE) THEN          IVMS(NUPD) = IVMS(NUPD) + 1          DO 20 J = 1, 6          VM(J) = VM(J)*XRAN(J)          VMSAV(NUPD,IVMS(NUPD),J) = VM(J)   20     CONTINUE        ELSE          DO 30 J = 1, 6          VM(J) = VMSAV(NUPD,IVMS(NUPD),J)   30     CONTINUE          IVMS(NUPD) = IVMS(NUPD) - 1        ENDIF      ENDIFC   40 RETURN      END